class Solution:
    def decodeMessage(self, key: str, message: str) -> str:
        def build_map(k: str) -> List[int]:
            mp = [-1] * 26
            nxt = 0
            for ch in k:
                if ch == " ":
                    continue
                idx = ord(ch) - ord("a")
                if mp[idx] == -1:
                    mp[idx] = nxt
                    nxt += 1
            return mp

        mp = build_map(key)
        out: list[str] = []
        for ch in message:
            if ch == " ":
                out.append(" ")
            else:
                out.append(chr(ord("a") + mp[ord(ch) - ord("a")]))
        return "".join(out)

